export function mergeBangla1Batches(batch1: Chapter[], batch2: Chapter[]): Chapter[] {
  const map = new Map<string, Chapter>();
  batch1.forEach((ch) => {
    map.set(ch.id, { ...ch, mcqs: [...ch.mcqs] });
  });
  batch2.forEach((ch) => {
    const existing = map.get(ch.id);
    if (existing) {
      const existingIds = new Set(existing.mcqs.map((m) => m.id));
      const extra = ch.mcqs.filter((m) => !existingIds.has(m.id));
      existing.mcqs = [...existing.mcqs, ...extra];
    } else {
      map.set(ch.id, { ...ch, mcqs: [...ch.mcqs] });
    }
  });
  return Array.from(map.values());
}
